  INSERT INTO FXNK_NBFXDMX_SH(NKZBBH,UUID,SWJGDM,DJXH,NSRSBH,NSRMC,NKJE,NKSE,NKYWMS,FSSJ,SJTBSJ)
         WITH YDCL AS (
       SELECT SHLC.UUID,JG.TSSWJG_DM_1,JG.DJXH,JG.SSQ,JG.SBPC,YD.SDHCRXMJH,YD.SDHCBGBH,
