              '【申报所属期-批次】'||YDCL.SSQ||'-'||YDCL.SBPC||'；【实地核查报告】'||YDCL.SDHCBGBH||
              '；【实地核查人员】'||YDCL.SDHCRXMJH||'；【审核人员】'||YDCL.SHRYXM||'；【复审人员】'||YDCL.FSRYXM,
